insert into public.categories (id, slug, name_en, name_ar, description_en, description_ar, image_url, sort_order) values
  ('c0000000-0000-4000-8000-000000000001', 'abaya', 'Abaya Fabrics', 'أقمشة العبايات', 'Nida, crepe and Korean crepe in deep, fluid blacks and soft neutrals.', 'ندى وكريب وكريب كوري بألوان سوداء عميقة وانسيابية وألوان هادئة.', null, 1),
  ('c0000000-0000-4000-8000-000000000002', 'thobe', 'Thobe Fabrics', 'أقمشة الثياب', 'Crisp Japanese and Korean blends for thobes that hold their shape all day.', 'خلطات يابانية وكورية ناعمة لثياب تحافظ على شكلها طوال اليوم.', null, 2),
  ('c0000000-0000-4000-8000-000000000003', 'cotton', 'Cotton', 'القطن', 'Breathable cottons for the Gulf summer, in plains and prints.', 'أقطان تسمح بمرور الهواء لصيف الخليج، سادة ومطبوعة.', null, 3),
  ('c0000000-0000-4000-8000-000000000004', 'silk', 'Silk & Satin', 'الحرير والساتان', 'Liquid drape and a soft sheen for evenings and occasions.', 'انسدال ناعم ولمعة هادئة للسهرات والمناسبات.', null, 4),
  ('c0000000-0000-4000-8000-000000000005', 'linen', 'Linen', 'الكتان', 'Textured, natural linens that only get better with wear.', 'كتان طبيعي بملمس مميز يزداد جمالاً مع الاستخدام.', null, 5),
  ('c0000000-0000-4000-8000-000000000006', 'chiffon', 'Chiffon & Georgette', 'الشيفون والجورجيت', 'Sheer, weightless layers for sheilas, sleeves and overlays.', 'طبقات شفافة وخفيفة للشيلات والأكمام والطبقات العلوية.', null, 6),
  ('c0000000-0000-4000-8000-000000000007', 'lace', 'Lace & Embroidered', 'الدانتيل والمطرّز', 'Delicate lace and embroidered panels for weddings and Eid.', 'دانتيل رقيق وقطع مطرّزة للأعراس والأعياد.', null, 7),
  ('c0000000-0000-4000-8000-000000000008', 'printed', 'Printed Fabrics', 'الأقمشة المطبوعة', 'Bold florals and geometrics, like the rolls in our shop window.', 'زهور جريئة ونقوش هندسية، كاللفّات في واجهة محلنا.', null, 8)
insert into public.materials (low_stock_m, min_order_m, step_m, is_active, slug, sku, category_id, name_en, name_ar, description_en, description_ar, composition, width_cm, weight_gsm, colour_name_en, colour_name_ar, colour_hex, pattern, occasions, price_fils, compare_at_fils, stock_m, is_featured, id) values
  (10, 0.5, 0.5, true, 'royal-nida-black', 'AB-NID-001', 'c0000000-0000-4000-8000-000000000001', 'Royal Nida', 'ندى ملكي', 'The classic abaya fabric — fluid, matte and opaque, with a fall that moves beautifully.', 'قماش العباية الكلاسيكي — انسيابي ومطفي وغير شفاف، بانسدال جميل.', '100% Polyester', 150, 140, 'Jet Black', 'أسود فاحم', '#121214', 'crepe', array['abaya', 'everyday']::text[], 1800, null, 240, true, 'd0000000-0000-4000-8000-000000000001'),
  (10, 0.5, 0.5, true, 'korean-crepe-onyx', 'AB-KCR-002', 'c0000000-0000-4000-8000-000000000001', 'Korean Crepe', 'كريب كوري', 'A heavier crepe with a fine pebbled surface. Holds pleats and tailoring well.', 'كريب أثقل بسطح محبّب ناعم. يحافظ على الكسرات والتفصيل.', '100% Polyester', 150, 190, 'Onyx', 'أونيكس', '#1c1b20', 'crepe', array['abaya', 'eid']::text[], 2500, 2900, 8, true, 'd0000000-0000-4000-8000-000000000002'),
  (10, 0.5, 0.5, true, 'zoom-crepe-taupe', 'AB-ZCR-003', 'c0000000-0000-4000-8000-000000000001', 'Zoom Crepe', 'كريب زوم', 'Soft, lightly stretchy crepe in a warm taupe — ideal for open abayas.', 'كريب ناعم بمرونة خفيفة بلون رمادي دافئ — مثالي للعبايات المفتوحة.', '95% Polyester, 5% Elastane', 150, 160, 'Taupe', 'رمادي بني', '#8a7a6a', 'crepe', array['abaya']::text[], 2200, null, 96, false, 'd0000000-0000-4000-8000-000000000003'),
  (10, 0.5, 0.5, true, 'japanese-thobe-white', 'TH-JAP-001', 'c0000000-0000-4000-8000-000000000002', 'Japanese Thobe Cloth', 'قماش ثوب ياباني', 'Crisp, cool and bright white. Resists creasing through a long day.', 'ناعم وبارد وأبيض ناصع. يقاوم التجعّد طوال اليوم.', '65% Polyester, 35% Viscose', 150, 175, 'Optic White', 'أبيض ناصع', '#f7f6f2', 'twill', array['thobe', 'eid', 'everyday']::text[], 3500, null, 320, true, 'd0000000-0000-4000-8000-000000000004'),
  (10, 0.5, 0.5, true, 'korean-thobe-ivory', 'TH-KOR-002', 'c0000000-0000-4000-8000-000000000002', 'Korean Thobe Cloth', 'قماش ثوب كوري', 'A softer hand with a subtle sheen, in a gentle winter ivory.', 'ملمس أنعم ولمعة خفيفة، بلون عاجي شتوي هادئ.', '70% Polyester, 30% Viscose', 150, 190, 'Ivory', 'عاجي', '#eee8da', 'twill', array['thobe']::text[], 2800, null, 140, false, 'd0000000-0000-4000-8000-000000000005'),
  (10, 0.5, 0.5, true, 'winter-thobe-slate', 'TH-WIN-003', 'c0000000-0000-4000-8000-000000000002', 'Winter Wool-Touch', 'صوف شتوي ناعم', 'Warm-handed thobe fabric in slate grey for the cooler months.', 'قماش ثوب دافئ الملمس باللون الرمادي للأشهر الباردة.', '80% Polyester, 20% Wool', 150, 240, 'Slate', 'رمادي أردوازي', '#5c6366', 'twill', array['thobe']::text[], 4200, null, 60, false, 'd0000000-0000-4000-8000-000000000006'),
  (10, 0.5, 0.5, true, 'summer-voile-print', 'CO-VOI-001', 'c0000000-0000-4000-8000-000000000003', 'Summer Voile Print', 'فوال صيفي مطبوع', 'Light cotton voile with a hand-drawn floral — made for house dresses and jalabiyas.', 'فوال قطني خفيف بنقشة زهور مرسومة يدوياً — مثالي لفساتين البيت والجلابيات.', '100% Cotton', 140, 90, 'Terracotta', 'طيني', '#c46f4c', 'floral', array['jalabiya', 'everyday']::text[], 500, null, 410, true, 'd0000000-0000-4000-8000-000000000007'),
  (10, 0.5, 0.5, true, 'poplin-sage', 'CO-POP-002', 'c0000000-0000-4000-8000-000000000003', 'Cotton Poplin', 'بوبلين قطني', 'Smooth, tightly woven poplin for shirts and children''s wear.', 'بوبلين ناعم محكم النسج للقمصان وملابس الأطفال.', '100% Cotton', 145, 115, 'Sage', 'أخضر مريمي', '#9caf94', 'plain', array['shirt', 'everyday']::text[], 450, null, 280, false, 'd0000000-0000-4000-8000-000000000008'),
  (10, 0.5, 0.5, true, 'mulberry-satin-wine', 'SI-SAT-001', 'c0000000-0000-4000-8000-000000000004', 'Mulberry Satin', 'ساتان التوت', 'A deep wine satin with a liquid drape. Beautiful for Eid and evening wear.', 'ساتان بلون نبيذي عميق بانسدال سائل. رائع للعيد والسهرات.', '100% Silk', 114, 90, 'Wine', 'نبيذي', '#6e2438', 'satin', array['eid', 'wedding', 'dress']::text[], 7500, 8900, 34, true, 'd0000000-0000-4000-8000-000000000009'),
  (10, 0.5, 0.5, true, 'duchess-satin-champagne', 'SI-DUC-002', 'c0000000-0000-4000-8000-000000000004', 'Duchess Satin', 'ساتان دوتشيس', 'Structured, luminous satin in champagne gold for formal gowns.', 'ساتان متماسك ولامع بلون الشمبانيا الذهبي للفساتين الرسمية.', '100% Polyester', 150, 210, 'Champagne', 'شمبانيا', '#d8c08e', 'satin', array['wedding', 'dress']::text[], 3200, null, 75, false, 'd0000000-0000-4000-8000-000000000010'),
  (10, 0.5, 0.5, true, 'irish-linen-natural', 'LI-IRI-001', 'c0000000-0000-4000-8000-000000000005', 'Washed Linen', 'كتان مغسول', 'Stone-washed for a soft, lived-in hand straight off the roll.', 'مغسول بالحجر لملمس ناعم من أول استخدام.', '100% Linen', 140, 185, 'Natural Flax', 'كتان طبيعي', '#c8b99a', 'linen', array['shirt', 'dress', 'everyday']::text[], 3800, null, 52, true, 'd0000000-0000-4000-8000-000000000011'),
  (10, 0.5, 0.5, true, 'georgette-mist', 'CH-GEO-001', 'c0000000-0000-4000-8000-000000000006', 'Silk Georgette', 'جورجيت حريري', 'Sheer and softly crinkled — the go-to for sheilas and overlays.', 'شفاف بتجعيد ناعم — الخيار الأمثل للشيلات والطبقات العلوية.', '100% Polyester', 150, 60, 'Mist Blue', 'أزرق ضبابي', '#a9bcc8', 'chiffon', array['abaya', 'eid']::text[], 1500, null, 130, false, 'd0000000-0000-4000-8000-000000000012'),
  (10, 0.5, 0.5, true, 'chantilly-lace-ivory', 'LA-CHA-001', 'c0000000-0000-4000-8000-000000000007', 'Chantilly Lace', 'دانتيل شانتيلي', 'Fine floral lace with scalloped edges — a bridal favourite.', 'دانتيل زهري رقيق بحواف مموّجة — المفضل للعرائس.', '100% Nylon', 130, 70, 'Ivory', 'عاجي', '#efe6d6', 'lace', array['wedding', 'eid']::text[], 6500, null, 22, true, 'd0000000-0000-4000-8000-000000000013'),
  (10, 0.5, 0.5, true, 'garden-print-cobalt', 'PR-GAR-001', 'c0000000-0000-4000-8000-000000000008', 'Garden Print', 'نقشة الحديقة', 'Vivid cobalt and saffron florals — just like our shop window.', 'زهور زاهية بالأزرق والزعفراني — تماماً كواجهة محلنا.', '100% Viscose', 145, 110, 'Cobalt', 'أزرق كوبالت', '#2f4f9a', 'floral', array['jalabiya', 'dress', 'everyday']::text[], 350, 500, 520, true, 'd0000000-0000-4000-8000-000000000014'),
  (10, 0.5, 0.5, true, 'pinstripe-navy', 'PR-STR-002', 'c0000000-0000-4000-8000-000000000008', 'Pinstripe', 'مخطط رفيع', 'Classic navy pinstripe for tailored shirts and kids'' uniforms.', 'مخطط كحلي كلاسيكي للقمصان المفصّلة والزي المدرسي.', '60% Cotton, 40% Polyester', 150, 125, 'Navy', 'كحلي', '#24324f', 'stripe', array['shirt']::text[], 900, null, 160, false, 'd0000000-0000-4000-8000-000000000015')
